import{_ as e,o as a,c as d,a3 as r}from"./chunks/framework.BZCmpA0A.js";const b=JSON.parse('{"title":"10 · Shell 與 fan 編輯器","description":"","frontmatter":{},"headers":[],"relativePath":"topics/applications.md","filePath":"topics/applications.md","lastUpdated":1793165688000}'),l={name:"topics/applications.md"};function o(s,t,c,n,h,i){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="_10-·-shell-與-fan-編輯器" tabindex="-1">10 · Shell 與 fan 編輯器 <a class="header-anchor" href="#_10-·-shell-與-fan-編輯器" aria-label="Permalink to &quot;10 · Shell 與 fan 編輯器&quot;">​</a></h1><p><code>ls</code> 不帶參數時列出根目錄；<code>rm /absolute/file</code> 刪除檔案，<code>cp /absolute/source /absolute/destination</code> 複製檔案。<code>cls</code> 會要求終端清除畫面和捲動歷史，保留 WUFS 檔案；捲動歷史是否真的清除取決於終端對控制序列的支援。命令範圍與限制見 <a href="./../SPEC-18-file-commands.html">Spec 18</a>。</p><p>核心提供能力，使用者程式把能力組合成操作。WUWAOS 的 shell 與 fan 都是 U-mode（使用者模式）程式，透過 syscall 操作行程、終端與檔案。</p><h2 id="shell-如何執行命令" tabindex="-1">Shell 如何執行命令 <a class="header-anchor" href="#shell-如何執行命令" aria-label="Permalink to &quot;Shell 如何執行命令&quot;">​</a></h2><p><code>user/shell.c</code> 讀入最多 126 個字元，切成最多 4 個 token（以空白分隔的單位），再比對命令。解析為 O(L)，L 是輸入長度；目前沒有引號、腳本與一般背景工作控制。</p><p>在提示字元輸入 <code>help</code>，每行會列出一個命令及其參數，右側對齊用途說明；行程、檔案與記憶體操作用空白行分隔。<code>&lt;path&gt;</code> 表示絕對路徑，<code>&lt;page&gt;</code> 從 0 起算。格式與驗收見 <a href="./../SPEC-14-shell-help.html">Spec 14</a>。</p><table tabindex="0"><thead><tr><th>操作</th><th>主要流程</th></tr></thead><tbody><tr><td>ps／pcb</td><td>進核心查詢行程狀態</td></tr><tr><td>ls／cat／write／rm／cp</td><td>以路徑呼叫 WUFS 服務</td></tr><tr><td>cls</td><td>透過終端控制序列清除畫面及捲動歷史</td></tr><tr><td>run counter</td><td>fork 子行程，再 exec 指定內建程式 ID</td></tr><tr><td>writer | reader</td><td>建立固定管道與兩個端點行程</td></tr><tr><td>fan 路徑</td><td>fork → exec fan 並傳入路徑 → 父 shell 等待</td></tr><tr><td>vmstat／mem</td><td>查詢與操作使用者記憶體</td></tr></tbody></table><p>命令和 syscall 沒有一對一關係。以 fan 為例，一次編輯操作可能多次讀取按鍵、輸出控制碼，最後才寫入檔案。</p><h2 id="三份獨立使用者映像" tabindex="-1">三份獨立使用者映像 <a class="header-anchor" href="#三份獨立使用者映像" aria-label="Permalink to &quot;三份獨立使用者映像&quot;">​</a></h2><p>Makefile 將 shell、app、fan 分別連結為 ELF，再轉成 binary 嵌入核心。<code>kernel/user_image.S</code> 保存原始內容，VM 在需要時載入對應頁面。</p><p>因此 fan 是真正的獨立行程，但還不是由 <code>/bin/fan</code> 磁碟執行檔載入。user/entry.S 將初始參數交給 user_main，返回值再交給 exit。</p><h2 id="fan-的文字資料結構" tabindex="-1">fan 的文字資料結構 <a class="header-anchor" href="#fan-的文字資料結構" aria-label="Permalink to &quot;fan 的文字資料結構&quot;">​</a></h2><p><code>user/fan.c</code> 用連續 byte 陣列存放最多 2048 bytes ASCII／LF 文字，cursor（游標）是陣列中的位移。</p><p>例如 <code>abc</code> 的游標在 b 前面，插入 X 時，先把後段 <code>bc</code> 向右移，再放入 X，得到 <code>aXbc</code>。刪除則反方向搬移。插入／刪除最壞 O(N)，對小型文字檔容易理解與管理，不需要複雜樹結構。</p><p>上下移動會掃描換行並保留目標欄位；按鍵解碼器逐 byte 處理 ANSI Escape 序列。畫面以逐行快取比較，只重畫改變的行。</p><h2 id="一個終端上的全螢幕介面" tabindex="-1">一個終端上的全螢幕介面 <a class="header-anchor" href="#一個終端上的全螢幕介面" aria-label="Permalink to &quot;一個終端上的全螢幕介面&quot;">​</a></h2><p>畫面經 UART 輸出 ANSI 游標定位、清行與色彩控制碼，需至少 80×24 終端。它是 TUI（文字使用者介面），沒有 framebuffer（像素畫面緩衝區）或圖形視窗系統。</p><p>編輯器持有 raw console，shell 等待子行程，不會同時讀走你的按鍵；背景行程輸出仍可能干擾畫面，尚無完整前景工作隔離。</p><h2 id="在-qemu-編輯" tabindex="-1">在 QEMU 編輯 <a class="header-anchor" href="#在-qemu-編輯" aria-label="Permalink to &quot;在 QEMU 編輯&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fan /home/user/note.txt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>按鍵</th><th>操作</th></tr></thead><tbody><tr><td>方向鍵／Home／End</td><td>移動游標</td></tr><tr><td>Enter／Tab</td><td>換行／插入空白</td></tr><tr><td>Backspace／Delete</td><td>刪除文字</td></tr><tr><td>PageUp／PageDown</td><td>捲動畫面</td></tr><tr><td>Ctrl+O</td><td>儲存</td></tr><tr><td>Ctrl+X</td><td>離開；修改未儲存時詢問 y／n／c</td></tr><tr><td>Ctrl+L</td><td>完整重畫</td></tr></tbody></table><p>輸入文字，Ctrl+O 儲存，再 Ctrl+X 返回 shell，使用 <code>cat /home/user/note.txt</code> 讀回。新檔直到儲存才建立，父目錄必須存在。</p><h2 id="限制與參考" tabindex="-1">限制與參考 <a class="header-anchor" href="#限制與參考" aria-label="Permalink to &quot;限制與參考&quot;">​</a></h2><p>UTF-8、超大檔案與不支援的控制字元會拒絕開啟，以免截斷覆寫。既有 Tab 以 <code>&gt;</code> 顯示並保留，新 Tab 插入空白。目前沒有 undo、搜尋、Vim 命令模式與原子儲存。</p><p>觀念參考：<code>notes/ch3 Process.md</code>、<code>notes/ch12 I_O Systems.md</code>；終端序列依 <a href="https://invisible-island.net/xterm/ctlseqs/ctlseqs.html" target="_blank" rel="noreferrer">XTerm 文件</a>。設計與既有互動驗收見 <a href="./../SPEC-09-fan.html">Spec 09</a>。</p>',25)])])}const m=e(l,[["render",o]]);export{b as __pageData,m as default};
